/* Card set: Trains & Railroads (generated from the approved roster-final.csv by the Trains build, schema per tools/csv-to-set.js).
   (trains.js exceeds the comfortable push size, so the remaining cards live in
   trains-additions.js, which must stay directly after 'trains.js' in sets/manifest.js.) */
CardSets.register({"id":"trains","name":"Trains & Railroads","code":"TRAINS","description":"420 cards of steam, diesel and electric power — record-breaking locomotives, legendary expresses, grand stations and the heritage lines that keep them alive.","theme":{"primary":"#33566e","secondary":"#7a3b2e","artBackground":"#f2efe9","artFit":"cover"},"pack":{"name":"Train Pack","emblem":"🚂","skin":"trains"},"cards":[{"name":"Union Pacific Big Boy 4014","rarity":"chase","id":"union-pacific-big-boy-4014","subtitle":"Steam Locomotives","details":"Union Pacific's 4-8-8-4 Big Boy of 1941 was among the largest steam locomotive types ever built, and No. 4014 became the fleet's celebrated restored example.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Union%20Pacific%20Big%20Boy%204014%20Cajon%20Summit%20October%2013th%2C%202019.jpg?width=1024"},{"name":"Flying Scotsman","rarity":"chase","id":"flying-scotsman","subtitle":"Steam Locomotives","details":"LNER A3 Pacific Flying Scotsman, built in 1923 as No. 4472, was the first locomotive in Britain officially recorded travelling at 100 miles per hour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LNER%20A3%20Class%204472%20Flying%20Scotsman%20Stratford%20Upon%20Avon%20Station.jpg?width=1024"},{"name":"Mallard","rarity":"chase","id":"mallard","subtitle":"Steam Locomotives","details":"LNER A4 Pacific Mallard, built in 1938 as No. 4468, set the world speed record for steam traction at 126 miles per hour on a test run that year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Number%204468%20Mallard%20in%20York.jpg?width=1024"},{"name":"NYC Hudson","rarity":"chase","id":"nyc-hudson","subtitle":"Steam Locomotives","details":"New York Central's streamlined J-3a Hudson of 1937, a 4-6-4 in Art Deco casing, became the defining passenger icon of the Hudson River route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New%20York%20Central%20No.%205445.jpg?width=1024"},{"name":"Pere Marquette 1225","rarity":"chase","id":"pere-marquette-1225","subtitle":"Steam Locomotives","details":"Pere Marquette N-1 Berkshire No. 1225, a Lima-built 2-8-4 of 1941, hauled fast freight across Michigan before a second career as an excursion star.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steam%20Railroading%20Institute%20Pere%20Marquette%201225%20%281%29.jpg?width=1024"},{"name":"Stephenson's Rocket","rarity":"legendary","id":"stephensons-rocket","subtitle":"Steam Locomotives","details":"Stephenson's Rocket, an 0-2-2 built by George and Robert Stephenson in 1829, won the Rainhill Trials and proved steam haulage for passenger railways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stephenson%27s%20Rocket%202.jpg?width=1024"},{"name":"Union Pacific Challenger 3985","rarity":"legendary","id":"union-pacific-challenger-3985","subtitle":"Steam Locomotives","details":"Union Pacific Challenger No. 3985, a 4-6-6-4 articulated locomotive built in 1943, was the second-largest steam type on the railroad after the Big Boy class.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Union%20Pacific%20Challenger%203985%2001.jpg?width=1024"},{"name":"Southern Pacific Daylight 4449","rarity":"legendary","id":"southern-pacific-daylight-4449","subtitle":"Steam Locomotives","details":"Southern Pacific GS-4 Northern No. 4449, built in 1941, wore the red-and-orange Daylight colours on celebrated streamlined passenger trains of the West Coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern%20Pacific%204449%20Daylight%20Running%20in%20Fife%202007.jpg?width=1024"},{"name":"Norfolk & Western 611","rarity":"legendary","id":"norfolk-and-western-611","subtitle":"Steam Locomotives","details":"Norfolk and Western Class J Northern No. 611, built at Roanoke in 1950, was the streamlined flagship of a railroad famed for designing its own locomotives.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Norfolk%20%26%20Western%20611%20J%20Class.jpg?width=1024"},{"name":"LNER A1 Tornado","rarity":"legendary","id":"lner-a1-tornado","subtitle":"Steam Locomotives","details":"LNER Peppercorn A1 Pacific Tornado, No. 60163 completed in 2008, was the first new main-line steam locomotive built in Britain since 1960.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flax%20Bourton%20railway%20station%20MMB%2031%20Tornado%2060163.jpg?width=1024"},{"name":"Princess Coronation Class","rarity":"legendary","id":"princess-coronation-class","subtitle":"Steam Locomotives","details":"Stanier's Princess Coronation Pacifics of 1937, in streamlined casing, powered the LMS Coronation Scot expresses between London and Glasgow in style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LMS%20Coronation%20Class%206233%20Duchess%20of%20Sutherland%20Locomotive%20Chester%20Station%20%281%29.jpg?width=1024"},{"name":"Pennsylvania K4s","rarity":"legendary","id":"pennsylvania-k4s","subtitle":"Steam Locomotives","details":"The Pennsylvania Railroad K4s Pacific of 1914, a 4-6-2 built in large numbers, served for decades as the standard passenger locomotive of the system.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PRR%20K4%204-6-2%201361%20on%20display%20at%20Horseshoe%20Curve%2C%20PA%20on%20February%2023%2C%201969%20%2825145573673%29.jpg?width=1024"},{"name":"JNR Class C62","rarity":"legendary","id":"jnr-class-c62","subtitle":"Steam Locomotives","details":"Japan's C62 Hudson of 1948, a 4-6-4 express design, was the largest and fastest steam passenger locomotive type operated by Japanese National Railways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JNR%20Class%20C62%2026%20Kyoto%20Railway%20Museum%2020-09-2024.jpg?width=1024"},{"name":"Union Pacific 844","rarity":"epic","id":"union-pacific-844","subtitle":"Steam Locomotives","details":"Union Pacific FEF-3 Northern No. 844, delivered in 1944, earned lasting fame as a Union Pacific steam locomotive that was never formally retired.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Union%20Pacific%20844%2C%20Painted%20Rocks%2C%20NV%2C%202009%20%28crop%29.jpg?width=1024"},{"name":"GWR King Class","rarity":"epic","id":"gwr-king-class","subtitle":"Steam Locomotives","details":"The Great Western 6000 Class King of 1927, a four-cylinder 4-6-0, was the company's most powerful express passenger design of the steam era.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GWR%20King%20Class%20No%206024%20King%20Edward%20I%20%282999357229%29.jpg?width=1024"},{"name":"GWR Castle Class","rarity":"epic","id":"gwr-castle-class","subtitle":"Steam Locomotives","details":"The Great Western Castle Class of 1923, a 4-6-0 design including Caerphilly Castle, gave the company a long-lived and influential express locomotive.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GWR%204073%20Class%20Caerphilly%20Castle%20Locomotive%20Swindon%20Great%20Western%20Museum.jpg?width=1024"},{"name":"LMS Black Five","rarity":"epic","id":"lms-black-five","subtitle":"Steam Locomotives","details":"Stanier's LMS Class 5 of 1934, a 4-6-0 nicknamed the Black Five, was a versatile mixed-traffic workhorse built in the hundreds for work across the system.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/45212%2C%20a%20%27Black%20Five%27%20at%20Inverlochy%20-%20geograph.org.uk%20-%205357227.jpg?width=1024"},{"name":"BR Standard Class 9F","rarity":"epic","id":"br-standard-class-9f","subtitle":"Steam Locomotives","details":"The BR Standard Class 9F of 1954, a powerful 2-10-0 freight design, closed British standard steam construction, with Evening Star as its final example.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BR%20Standard%20Class%209F%2092220%20Evening%20Star%20National%20Railway%20Museum.jpg?width=1024"},{"name":"DRG Class 01 Pacific","rarity":"epic","id":"drg-class-01","subtitle":"Steam Locomotives","details":"The Deutsche Reichsbahn Class 01 Pacific of 1926, a standardised 4-6-2 design, became the flagship express locomotive of Germany's unified railway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DB%20Baureihe%2001%2001-202%20-%20Verein%20Pacific%2001-202%20%2828204552013%29.jpg?width=1024"},{"name":"Locomotion No. 1","rarity":"epic","id":"locomotion-no-1","subtitle":"Steam Locomotives","details":"Locomotion No. 1, George Stephenson's 0-4-0 of 1825, hauled the opening train of the Stockton and Darlington Railway, the first public steam railway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Locomotion%20No.%201%20New%20Bridge.jpg?width=1024"},{"name":"Canadian Pacific Royal Hudson","rarity":"epic","id":"canadian-pacific-royal-hudson","subtitle":"Steam Locomotives","details":"Canadian Pacific's semi-streamlined H1 Hudsons of 1937 earned the Royal Hudson name after hauling a royal train tour across Canada in 1939.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Royal%20Hudson%202860%20train.jpg?width=1024"},{"name":"C&O Allegheny","rarity":"epic","id":"chesapeake-and-ohio-allegheny","subtitle":"Steam Locomotives","details":"The Chesapeake and Ohio H-8 Allegheny of 1941, a 2-6-6-6 articulated giant, ranked among the most powerful steam locomotives ever placed in service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chesapeake%20%26%20Ohio%20H-8%20Class%20Steam%20Locomotive%20No.%201601%20at%20Henry%20Ford%20Museum%2C%20February%202018.jpg?width=1024"},{"name":"South African Class 25NC","rarity":"epic","id":"south-african-class-25nc","subtitle":"Steam Locomotives","details":"South Africa's Class 25NC, a 4-8-4 Northern introduced in 1953, was a large non-condensing design built for long hauls across the arid Karoo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/047.%201980-12.%20Goods%20train%20leaving%20De%20Aar.%20Class%2025NC%203522%20ELBE%20-%20South%20African%20Railways.jpg?width=1024"},{"name":"Australian AD60 Garratt","rarity":"rare","id":"australian-ad60-garratt","subtitle":"Steam Locomotives","details":"New South Wales' AD60 Beyer-Garratt of 1952, articulated as a 4-8-4+4-8-4, was among the largest steam locomotive types ever used in Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AD60%20class%20Beyer-Garratt%20Locomotive%20No.%206022%2C%20Newcastle%20NSW%20c.1968.jpg?width=1024"},{"name":"Indian WP Class","rarity":"rare","id":"indian-wp-class","subtitle":"Steam Locomotives","details":"India's WP Pacific of 1947, a streamlined 4-6-2 design, became the signature post-war express locomotive of Indian Railways' broad-gauge network.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/66-271%20Steam%20engine%20nr%20Calcutta%20India%201966%20%2851192981441%29.jpg?width=1024"},{"name":"LMS Jubilee Class","rarity":"rare","id":"lms-jubilee-class","subtitle":"Steam Locomotives","details":"Stanier's LMS Jubilee Class of 1934, a 4-6-0 express design, took its name from the Silver Jubilee and carried names of places across the Empire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jubilee%20Class%206P%20N%C2%B0%2045596%20Bahamas.jpg?width=1024"},{"name":"SR Merchant Navy Class","rarity":"rare","id":"sr-merchant-navy-class","subtitle":"Steam Locomotives","details":"Bulleid's Merchant Navy Pacifics of 1941 wore distinctive air-smoothed casing and hauled Southern Railway boat trains to the Channel ports.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern%20Railway%20Merchant%20Navy%20Class%2035028%20%22Clan%20Line%22%20at%20Basingstoke.jpg?width=1024"},{"name":"GWR Hall Class","rarity":"rare","id":"gwr-hall-class","subtitle":"Steam Locomotives","details":"The Great Western Hall Class of 1928, a two-cylinder 4-6-0, was a capable mixed-traffic design named after country houses across the West of England.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GWR%20Hall%20class%204965%20Rood%20Ashton%20Hall%20and%20Castle%20class%205043%20Earl%20of%20Mount%20Edgcumbe%20on%20The%20Cornishman%2C%20Teignmouth%2C%2027%20April%202013%20%282%29.jpg?width=1024"},{"name":"USRA Light Mikado","rarity":"rare","id":"usra-light-mikado","subtitle":"Steam Locomotives","details":"The USRA Light Mikado of 1918, a standardised 2-8-2 freight design, was widely copied and became a defining American locomotive of the First World War era.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USRA%20Light%20Mikado%20locomotive.jpg?width=1024"},{"name":"Nickel Plate Road 765","rarity":"rare","id":"nickel-plate-road-765","subtitle":"Steam Locomotives","details":"Nickel Plate Road S-2 Berkshire No. 765, a Lima-built 2-8-4 of 1944, was preserved to become one of America's best-known main-line excursion engines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nickel%20Plate%20Road%20765%20Steam%20Locomotive%20%2851466852677%29.jpg?width=1024"},{"name":"Santa Fe 3751","rarity":"rare","id":"santa-fe-3751","subtitle":"Steam Locomotives","details":"Santa Fe No. 3751, a 4-8-4 Northern delivered in 1927, was the first locomotive of its type built for the Atchison, Topeka and Santa Fe Railway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/3751%20in%20the%20yard%20July%202017.jpg?width=1024"},{"name":"DRG Class 44","rarity":"rare","id":"drg-class-44","subtitle":"Steam Locomotives","details":"Germany's Class 44 of 1926, a three-cylinder 2-10-0 Decapod, was the Reichsbahn's standard heavy freight locomotive for demanding main-line work.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DB%20Class%20%22044%22%20%28DRG%20Class%20%2244%22%20retaining%20coal%20firing%29%202-10-0%20No.044%20328%20-%2031674956314.jpg?width=1024"},{"name":"JNR Class D51","rarity":"rare","id":"jnr-class-d51","subtitle":"Steam Locomotives","details":"Japan's D51 Mikado of 1936, a 2-8-2 freight design, was built in greater numbers than any other Japanese steam class and defined the freight fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JNR%20D51-745.jpg?width=1024"},{"name":"NSWGR C38 Class","rarity":"rare","id":"nswgr-c38-class","subtitle":"Steam Locomotives","details":"New South Wales' C38 Pacific of 1943, including streamlined No. 3801, was the state's celebrated express design for premier passenger services.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NSWGR%203801%20Preserved%20New%20South%20Wales%20C38%20class%204-6-2%20locomotive%201.jpg?width=1024"},{"name":"SNCF 141 R","rarity":"rare","id":"sncf-141-r","subtitle":"Steam Locomotives","details":"The SNCF 141 R Mikados of 1945, built in the United States and Canada, formed a huge 2-8-2 fleet that helped rebuild France's railways after the war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mikado%20141.R.1244%20Bad%20Zurzach.jpg?width=1024"},{"name":"Puffing Billy","rarity":"rare","id":"puffing-billy-1813","subtitle":"Steam Locomotives","details":"Puffing Billy, William Hedley's 0-4-0 colliery locomotive of 1813 at Wylam, survives as one of the oldest steam locomotives anywhere in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Puffing%20Billy%20side%20Science%20Museum%20London.jpg?width=1024"},{"name":"GWR Iron Duke","rarity":"rare","id":"gwr-iron-duke","subtitle":"Steam Locomotives","details":"Gooch's Iron Duke of 1847, a broad-gauge 4-2-2 express locomotive, was built for Brunel's Great Western main line and its celebrated high speeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/IRON%20DUKE%20replica%20National%20Railway%20Museum.jpg?width=1024"},{"name":"John Bull","rarity":"uncommon","id":"john-bull-locomotive","subtitle":"Steam Locomotives","details":"John Bull, a Stephenson-built 2-4-0 shipped from Britain in 1831, hauled early trains for New Jersey's Camden and Amboy Railroad in the United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Bull%20locomotive%20at%20the%20National%20Museum%20of%20American%20History%20in%20Washington%2C%20DC.%20-%20January%202009.jpg?width=1024"},{"name":"Best Friend of Charleston","rarity":"uncommon","id":"best-friend-of-charleston","subtitle":"Steam Locomotives","details":"Best Friend of Charleston, an 0-4-0 built in 1830, was the first locomotive constructed in the United States for regular passenger service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Best%20Friend%20of%20Charleston%2C%20Southern%20Railway%20System%20%2832714098016%29.jpg?width=1024"},{"name":"LNER Class V2","rarity":"uncommon","id":"lner-class-v2","subtitle":"Steam Locomotives","details":"Gresley's LNER Class V2 of 1936, a 2-6-2 Prairie design including Green Arrow, was a powerful mixed-traffic type for fast freight and passenger work.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/V2%20No%204771%20Green%20Arrow%20at%20Rainhill.jpg?width=1024"},{"name":"LNER Class B1","rarity":"uncommon","id":"lner-class-b1","subtitle":"Steam Locomotives","details":"Thompson's LNER Class B1 of 1942, a 4-6-0 austerity design, was a simple and economical mixed-traffic locomotive built in large wartime numbers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/No.61306%20Mayflower%20LNER%20Thompson%20Class%20B1%20%286163851645%29.jpg?width=1024"},{"name":"SR Schools Class","rarity":"uncommon","id":"sr-schools-class","subtitle":"Steam Locomotives","details":"The Southern Railway Schools Class of 1930, a compact 4-4-0 express design, carried the names of famous public schools across the south of England.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SR%20Schools%20Class%20V%2030925%20Cheltenham.jpg?width=1024"},{"name":"BR Standard Class 5","rarity":"uncommon","id":"br-standard-class-5","subtitle":"Steam Locomotives","details":"The BR Standard Class 5 of 1951, a 4-6-0 mixed-traffic design by Riddles, drew directly on the proven LMS Black Five for post-war British service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/No.73129%20Class%205%20Steam%20Loco%20%286159496355%29.jpg?width=1024"},{"name":"DRG Class 50","rarity":"uncommon","id":"drg-class-50","subtitle":"Steam Locomotives","details":"Germany's Class 50 of 1939, a versatile 2-10-0 Decapod, was a standard freight design built in large numbers across factories in occupied Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dampflokomotive%2050%203708-0.jpg?width=1024"},{"name":"DRG Class 38 (P8)","rarity":"uncommon","id":"drg-class-38","subtitle":"Steam Locomotives","details":"The Prussian P 8 of 1906, later German Class 38, was a widely used 4-6-0 passenger locomotive adopted by railways across Germany and beyond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prussian%20P8-P1330749%20N.jpg?width=1024"},{"name":"JNR Class C57","rarity":"uncommon","id":"jnr-class-c57","subtitle":"Steam Locomotives","details":"Japan's C57 Pacific of 1937, an elegant 4-6-2 passenger design nicknamed the Lady, was admired for its balanced proportions and smooth running.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JNR%20C57%20180%2020070818.jpg?width=1024"},{"name":"South African Class 15F","rarity":"uncommon","id":"south-african-class-15f","subtitle":"Steam Locomotives","details":"South Africa's Class 15F of 1938, a 4-8-2 Mountain type, was built in large numbers as a general-purpose main-line locomotive for varied duties.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/020.%201980-12.%20Class%2015F%20at%20Germiston%20%28SA%29%20Depot%20-%20South%20African%20Railways.jpg?width=1024"},{"name":"SNCF 231 E Chapelon","rarity":"uncommon","id":"sncf-231-e-chapelon","subtitle":"Steam Locomotives","details":"Andre Chapelon's rebuilt SNCF 231 E Pacifics of the 1930s, compound 4-6-2 locomotives, earned fame for exceptional efficiency and record economy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nord%20Chapelon%204-6-2%20No31192%20%28Blanc-Misseron%20421%201936%29%20became%20SNCF%20231E22.JPG?width=1024"},{"name":"Soviet FD Class","rarity":"uncommon","id":"soviet-fd-class","subtitle":"Steam Locomotives","details":"The Soviet FD class of 1931, a 2-10-2 named for Felix Dzerzhinsky, became the standard heavy freight locomotive of the Soviet Union's railways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soviet%20locomotive%20class%20FD.jpg?width=1024"},{"name":"New Zealand Ja Class","rarity":"uncommon","id":"new-zealand-ja-class","subtitle":"Steam Locomotives","details":"New Zealand's Ja class of 1946, a 4-8-2 design, was the largest steam class in the country, built for North Island main-line express services.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JA1271%20crossing%20the%20Otaki%20River.jpg?width=1024"},{"name":"B&O President Washington","rarity":"uncommon","id":"bo-president-washington","subtitle":"Steam Locomotives","details":"Baltimore and Ohio P-7 Pacific No. 5300, President Washington of 1927, was the flagship of the President class built for premier passenger service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/B%26O%20Railroad%20Museum%20B%26O%205300.jpg?width=800"},{"name":"Milwaukee Road Class F7","rarity":"uncommon","id":"milwaukee-road-f7-hudson","subtitle":"Steam Locomotives","details":"Milwaukee Road's streamlined Class F7 Hudsons of 1937, Baltic 4-6-4 locomotives, were built to haul the celebrated Hiawatha express trains.","image":"https://www.trains.com/wp-content/uploads/2020/10/20190218-1024x655.jpg"},{"name":"NYC Mohawk","rarity":"uncommon","id":"nyc-mohawk","subtitle":"Steam Locomotives","details":"New York Central's L-3 Mohawk of 1940, a dual-service 4-8-2, took the name Mohawk in place of Mountain on a railroad that avoided the older term.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New%20York%20Central%20-2933%20%E2%80%9CMohawk%20Locomotive%E2%80%9D%2C%20America%20Locomotive%20Company%2C%201929.jpg?width=1024"},{"name":"Reading T-1","rarity":"uncommon","id":"reading-t-1","subtitle":"Steam Locomotives","details":"The Reading T-1 Northerns of 1945, 4-8-4 locomotives rebuilt in the railroad's own shops, included No. 2101, famed for later excursion service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/P5081531%20Reading%20Company%202101.jpg?width=1024"},{"name":"Canadian Pacific G5 Pacific","rarity":"uncommon","id":"canadian-pacific-g5","subtitle":"Steam Locomotives","details":"Canadian Pacific's G5 Pacifics of 1946, light 4-6-2 locomotives, were built for branch-line and secondary passenger work across the system.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canadian%20Pacific%201201%20%2832714092586%29.jpg?width=1024"},{"name":"Indian YP Class","rarity":"uncommon","id":"indian-yp-class","subtitle":"Steam Locomotives","details":"India's YP Pacific of 1949, a 4-6-2 design, became the standard metre-gauge express locomotive for passenger services across the Indian network.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mysuru%20Rail%20Museum%20-%20Locomotive%20YP%202511%20-%202.jpg?width=1024"},{"name":"Victorian Railways R Class","rarity":"uncommon","id":"victorian-railways-r-class","subtitle":"Steam Locomotives","details":"Victorian Railways' R Class Hudsons of 1951, a 4-6-4 design, were the last new steam locomotives ordered for express services in Victoria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R%20class%20steam%20locomotive%20R707%20%27City%20of%20Melbourne%27%20during%20the%202026%20Steamrail%20Open%20Day%20at%20the%20Newport%20Railway%20Workshops%20in%20Newport%2C%20Melbourne%20-%2055141401064.jpg?width=1024"},{"name":"GWR 5700 Pannier Tank","rarity":"common","id":"gwr-pannier-tank-5700","subtitle":"Steam Locomotives","details":"The Great Western 5700 pannier tank of 1929, an 0-6-0PT, became the archetypal company shunter and branch engine, with pannier tanks on its boiler.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pannier%20tank%205764%2C%20at%20Minehead%20-%20geograph.org.uk%20-%202214463.jpg?width=1024"},{"name":"LMS 3F Jinty","rarity":"common","id":"lms-jinty-3f","subtitle":"Steam Locomotives","details":"The LMS Fowler 3F Jinty of 1924, an 0-6-0 tank engine, was a familiar shunter built for yard work and short-trip freight across the Midland system.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/31I10I2018%20British%20Railways%20Class%203F%20Jinty%20No%2047406%20Visits%20NVR%20C3.jpg?width=1024"},{"name":"BR Standard Class 4 Tank","rarity":"common","id":"br-standard-class-4-tank","subtitle":"Steam Locomotives","details":"The BR Standard Class 4 tank of 1951, a 2-6-4T by Riddles, was designed for suburban and branch passenger work on Britain's post-war railway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BR%20Standard%20Class%204%202-6-4%2080072%20%288063183612%29.jpg?width=800"},{"name":"GWR 1400 Class","rarity":"common","id":"gwr-1400-class","subtitle":"Steam Locomotives","details":"The Great Western 1400 Class of 1932, a small 0-4-2 tank engine, became famous for push-pull auto-trains on quiet rural branch lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1420%20Bulliver%20Exeter%20Railfair%20may%201994.jpg?width=1024"},{"name":"LMS Fowler 4F","rarity":"common","id":"lms-fowler-4f","subtitle":"Steam Locomotives","details":"The LMS Fowler 4F, an 0-6-0 freight design of Midland origin from 1911, was a long-lived general goods engine nicknamed the Duck Six.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LMS%204F%200-6-0%20No%204027%20at%20Rainhill.jpg?width=1024"},{"name":"Hunslet Austerity 0-6-0ST","rarity":"common","id":"hunslet-austerity-0-6-0st","subtitle":"Steam Locomotives","details":"Hunslet's Austerity saddle tank of 1943, a rugged 0-6-0ST, was built in large numbers as an industrial and military shunter for wartime service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hunslet%20Austerity%200-6-0%20saddle%20tank%2068030%20at%20Barrow%20Hill%20-%20geograph.org.uk%20-%202903628.jpg?width=1024"},{"name":"Peckett 0-4-0ST","rarity":"common","id":"peckett-0-4-0st","subtitle":"Steam Locomotives","details":"Peckett's small 0-4-0 saddle tanks, built in Bristol, were the typical factory and dock shunters of industrial Britain, compact and hard-wearing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SDJR%20Saddle%20Tank%20Kilmersdon%20at%20Washford%20on%20West%20Somerset%20Railway%20%288581188534%29.jpg?width=1024"},{"name":"SR USA Class","rarity":"common","id":"sr-usa-class","subtitle":"Steam Locomotives","details":"The Southern Railway USA Class of 1942, an 0-6-0 dock tank, adapted the US Army S100 design for heavy shunting work at Southampton Docks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Class%20USA%200-6-0T.jpg?width=1024"},{"name":"USRA 0-6-0 Switcher","rarity":"common","id":"usra-0-6-0-switcher","subtitle":"Steam Locomotives","details":"The USRA 0-6-0 switcher of 1918, a First World War standard yard design, was copied by railroads across the United States for shunting duties.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USRA%200-6-0.jpg?width=1024"},{"name":"USRA 0-8-0 Switcher","rarity":"common","id":"usra-0-8-0-switcher","subtitle":"Steam Locomotives","details":"The American heavy 0-8-0 switcher of the 1920s, a powerful yard design, was built for hump and transfer work in the busiest freight terminals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USRA%200-8-0.jpg?width=1024"},{"name":"Porter 0-4-0 Saddle Tank","rarity":"common","id":"porter-0-4-0-saddle-tank","subtitle":"Steam Locomotives","details":"H.K. Porter's compact 0-4-0 saddle tanks were a staple American industrial locomotive, serving mills, mines and docks across the United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antelope%20%26%20Western%20Porter%20locomotive.jpg?width=1024"},{"name":"Baldwin Consolidation 2-8-0","rarity":"common","id":"baldwin-consolidation-2-8-0","subtitle":"Steam Locomotives","details":"The Baldwin 2-8-0 Consolidation, a standard American freight type around 1900, earned its name by consolidating power for heavy goods trains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/D%26RGW%20-318%2C%202-8-0%20%22Consolidation%22%20Steam%20Locomotive%2C%20Baldwin%2C%201896.jpg?width=1024"},{"name":"American Type 4-4-0","rarity":"common","id":"american-4-4-0","subtitle":"Steam Locomotives","details":"The 4-4-0 American type of the mid-1800s, often a wood-burner with a tall balloon stack, was the classic locomotive of early United States railroads.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20General%2C%20Western%20%26%20Atlantic%20RR%20Locomotive%20Stolen%20in%20Andrews%20Raid%2C%201862.jpg?width=1024"},{"name":"Tom Thumb","rarity":"common","id":"tom-thumb-locomotive","subtitle":"Steam Locomotives","details":"Built by Peter Cooper in 1830, this tiny 0-2-2 vertical-boiler engine proved steam could handle the Baltimore and Ohio's sharp curves and steep grades.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2c/Tom_thumb_peter_coopers_iron_horse_6092027.jpg"},{"name":"DeWitt Clinton","rarity":"common","id":"dewitt-clinton-locomotive","subtitle":"Steam Locomotives","details":"This 0-4-0 of 1831 hauled the Mohawk and Hudson Railroad's first steam train in New York State, running in stagecoach-style coaches to Schenectady.","image":"https://upload.wikimedia.org/wikipedia/commons/8/88/DeWitt_Clinton_%28locomotive%29.jpg"},{"name":"DRG Class 64 Tank","rarity":"common","id":"drg-class-64-tank","subtitle":"Steam Locomotives","details":"Germany's Class 64 was a standard 2-6-2 tank engine of 1928, its rounded cab roof earning it the Bubikopf name on branch-line passenger work nationwide.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Dampflok_in_Marbach_-_geo.hlipp.de_-_1595.jpg"},{"name":"DRG Class 86 Tank","rarity":"common","id":"drg-class-86-tank","subtitle":"Steam Locomotives","details":"Germany's Class 86 was a standard 2-8-2 tank engine of 1928, built as the heavier branch-line and freight companion to the lighter Class 64.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9c/DR_Baureihe_86.jpg"},{"name":"JNR Class C11","rarity":"common","id":"jnr-class-c11","subtitle":"Steam Locomotives","details":"Japan's Class C11 was a 2-6-4 tank engine introduced in 1932, becoming the standard JNR design for local and suburban passenger services across the country.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/JNR_C11_207_20140928_002.jpg/1280px-JNR_C11_207_20140928_002.jpg"},{"name":"JNR Class 9600","rarity":"common","id":"jnr-9600-class","subtitle":"Steam Locomotives","details":"Japan's Class 9600 was a 2-8-0 Consolidation introduced in 1913, the first mass-produced Japanese freight locomotive design, built in the hundreds.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/JNR_9600_49699.png/1280px-JNR_9600_49699.png"},{"name":"JNR Class C56","rarity":"common","id":"jnr-class-c56","subtitle":"Steam Locomotives","details":"Japan's Class C56 was a light 2-6-0 Mogul of 1935, built for lightly laid branch lines at home and sent to wartime service in Thailand and Burma.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/C56_160_steam_locomotive_2018-05-05.jpg/1280px-C56_160_steam_locomotive_2018-05-05.jpg"},{"name":"Victorian Railways J Class","rarity":"common","id":"victorian-railways-j-class","subtitle":"Steam Locomotives","details":"Victoria's J Class was a 2-8-0 introduced in 1954, the last steam class built for Victorian Railways, designed for branch-line freight and shunting.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Victorian_Railways_J_class_locomotive_No._507_by_the_lake_at_dawn_Mulwala_NSW_-_December_2021.jpg/1280px-Victorian_Railways_J_class_locomotive_No._507_by_the_lake_at_dawn_Mulwala_NSW_-_December_2021.jpg"},{"name":"NSWGR Z19 Class","rarity":"common","id":"nswgr-z19-class","subtitle":"Steam Locomotives","details":"The Z19 Class was a Beyer, Peacock 2-6-0 goods design of 1877 that gave New South Wales decades of service on freight, mixed traffic and branch lines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/NSWR_Robert_Stephenson_long_boilered_type_Class_Z19.jpg/1280px-NSWR_Robert_Stephenson_long_boilered_type_Class_Z19.jpg"},{"name":"South African Class 6","rarity":"common","id":"south-african-class-6","subtitle":"Steam Locomotives","details":"The Class 6 was a 4-6-0 ten-wheeler family from 1893, built for the Cape Government Railways and used on passenger and goods work across southern Africa.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/SAR_Class_6_439_%284-6-0%29_ex_CGR_368-568-OVGS_68-CSAR_344.jpg/1280px-SAR_Class_6_439_%284-6-0%29_ex_CGR_368-568-OVGS_68-CSAR_344.jpg"},{"name":"South African Class 19D","rarity":"common","id":"south-african-class-19d","subtitle":"Steam Locomotives","details":"The Class 19D was a 4-8-2 Mountain type of 1937, a light-axle-load design built in large numbers for branch and secondary lines across South Africa.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/SAR_Class_19D_No._2685_-_Wesley_-_Umgeni_Steam_Railway.jpg/1280px-SAR_Class_19D_No._2685_-_Wesley_-_Umgeni_Steam_Railway.jpg"},{"name":"Polish TKt48","rarity":"common","id":"polish-tkt48","subtitle":"Steam Locomotives","details":"Poland's TKt48 was a 2-8-2 tank engine built from 1950, a Polish-designed type for local, suburban and light passenger services in the post-war fleet.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/2010-11-26-szczecin-gl%C3%B3wny-by-RalfR-83.jpg/1280px-2010-11-26-szczecin-gl%C3%B3wny-by-RalfR-83.jpg"},{"name":"Soviet 9P Tank","rarity":"common","id":"soviet-9p-tank","subtitle":"Steam Locomotives","details":"The Soviet 9P was an 0-6-0 industrial tank engine introduced in 1935, built for decades as the standard factory, dock and yard shunter of the USSR.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/9p_15387_Russian_Railway_Museum.jpg/1280px-9p_15387_Russian_Railway_Museum.jpg"},{"name":"Swedish B Class","rarity":"common","id":"swedish-b-class","subtitle":"Steam Locomotives","details":"Sweden's B Class was a 4-6-0 mixed-traffic design of 1909, the standard SJ locomotive of its era, with many examples surviving into preservation.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/B_1038_der_SJ_%28Statens_J%C3%A4rnv%C3%A4gar%29_bei_G%C3%A4vle_%28Sveriges_J%C3%A4rnv%C3%A4gsmuseum%29%2C_Schweden_1.jpg/1280px-B_1038_der_SJ_%28Statens_J%C3%A4rnv%C3%A4gar%29_bei_G%C3%A4vle_%28Sveriges_J%C3%A4rnv%C3%A4gsmuseum%29%2C_Schweden_1.jpg"},{"name":"Czech 310 Class (Coffee Pot)","rarity":"common","id":"czech-310-class-coffee-pot","subtitle":"Steam Locomotives","details":"The kkStB 97, later CSD 310.0, was a small 0-6-0 tank engine of 1878 built for local railways, nicknamed the Coffee Pot for its compact, upright shape.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Luzna_museum_CSD_310-076_2017-06-25.jpg/1280px-Luzna_museum_CSD_310-076_2017-06-25.jpg"},{"name":"EMD F7","rarity":"legendary","id":"emd-f7","subtitle":"Diesel & Electric","details":"EMD's F7 of 1949 was the definitive first-generation cab diesel, the streamlined F-unit that hauled American freight and passenger trains alike for decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/ATSF_309_%28Flickr_22322834666%29.jpg/1280px-ATSF_309_%28Flickr_22322834666%29.jpg"},{"name":"EMD E8","rarity":"legendary","id":"emd-e8","subtitle":"Diesel & Electric","details":"EMD's E8 of 1949 was a twin-engine streamlined passenger diesel, the E-unit that led the dieselisation of American long-distance trains after the war.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7a/Rock_Island_locomotive_652.jpg"},{"name":"ALCO PA","rarity":"legendary","id":"alco-pa","subtitle":"Diesel & Electric","details":"ALCO's PA of 1946 was a streamlined passenger cab unit, celebrated in Santa Fe Warbonnet livery and famed for its handsome, raked nose and smooth lines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/D%26H_19_at_Newtonville%2C_April_1978_postcard.jpg/960px-D%26H_19_at_Newtonville%2C_April_1978_postcard.jpg"},{"name":"British Rail Class 55 Deltic","rarity":"legendary","id":"br-class-55-deltic","subtitle":"Diesel & Electric","details":"The Class 55 Deltic of 1961 used twin Napier opposed-piston engines to power Britain's East Coast expresses at sustained high speed for two decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/55006_at_Finsbury_Park_Depot_on_03_July_1977_%28crop%29.jpg/1280px-55006_at_Finsbury_Park_Depot_on_03_July_1977_%28crop%29.jpg"},{"name":"EMD SD40-2","rarity":"legendary","id":"emd-sd40-2","subtitle":"Diesel & Electric","details":"EMD's SD40-2 of 1972 was a six-axle freight diesel that became among the best-selling American locomotives ever built and the yardstick of its era.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1d/MRL_250.jpg"},{"name":"EMD GP38-2","rarity":"epic","id":"emd-gp38-2","subtitle":"Diesel & Electric","details":"EMD's GP38-2 of 1972 was a 2,000 hp non-turbocharged four-axle road switcher, a simple and durable workhorse found on railroads everywhere in America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/BNSF_2273_Lincoln%2C_NE_3-13-14.jpg/1280px-BNSF_2273_Lincoln%2C_NE_3-13-14.jpg"},{"name":"GE Dash 9-44CW","rarity":"epic","id":"ge-dash-9-44cw","subtitle":"Diesel & Electric","details":"GE's Dash 9-44CW of 1993 was a 4,400 hp wide-cab freight diesel that became the standard North American main-line road locomotive of its generation.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/BNSF_4839-4485_In_Oregon_%28cropped%29.jpg/1280px-BNSF_4839-4485_In_Oregon_%28cropped%29.jpg"},{"name":"British Rail Class 43 (HST)","rarity":"epic","id":"br-class-43-hst","subtitle":"Diesel & Electric","details":"The Class 43 power car of 1975 led Britain's InterCity 125 High Speed Train, the 125 mph diesel formation that transformed British intercity travel.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/St_Philip%27s_Marsh_-_GWR_43002_Sir_Kenneth_Grange.JPG/1280px-St_Philip%27s_Marsh_-_GWR_43002_Sir_Kenneth_Grange.JPG"},{"name":"DB Class V200","rarity":"epic","id":"db-class-v200","subtitle":"Diesel & Electric","details":"The DB Class V200 of 1953 was a twin-engine diesel-hydraulic flagship, its streamlined form leading West German Bundesbahn express services of the era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/V_200_002_%2814.09.1985%29.jpg/1280px-V_200_002_%2814.09.1985%29.jpg"},{"name":"EMD FT","rarity":"epic","id":"emd-ft","subtitle":"Diesel & Electric","details":"EMD's FT of 1939 was the cab diesel whose coast-to-coast demonstrator tour proved that diesel freight power could replace steam on American main lines.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d3/ATSF_115_DL_1943.jpg"},{"name":"ALCO RS-3","rarity":"epic","id":"alco-rs-3","subtitle":"Diesel & Electric","details":"ALCO's RS-3 of 1950 was a versatile hood-unit road switcher, equally at home on freight, passenger and branch-line work across North America for decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/CNJ_1554_%286125339203%29.jpg/1280px-CNJ_1554_%286125339203%29.jpg"},{"name":"GE Genesis P42DC","rarity":"epic","id":"ge-genesis-p42dc","subtitle":"Diesel & Electric","details":"GE's Genesis P42DC of 1996 used a low monocoque body to cut weight and drag, becoming Amtrak's standard intercity passenger locomotive for a generation.","image":"https://upload.wikimedia.org/wikipedia/commons/a/aa/Borealis_in_Welch_Township%2C_May_2024_%28cropped%29.jpg"},{"name":"DB Class 103 Electric","rarity":"epic","id":"db-class-103","subtitle":"Diesel & Electric","details":"The DB Class 103 of 1965 was a six-axle electric flagship for TEE and InterCity trains, among Europe's fastest and most powerful electrics of its day.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Drei_Elektrolokomotiven_der_Baureihe_103_im_Bahnhof_Bremen-Hemelingen.jpg/1280px-Drei_Elektrolokomotiven_der_Baureihe_103_im_Bahnhof_Bremen-Hemelingen.jpg"},{"name":"EMD SD70ACe","rarity":"epic","id":"emd-sd70ace","subtitle":"Diesel & Electric","details":"EMD's SD70ACe of 2004 was a 4,300 hp AC-traction freight diesel, the heavy-haul successor in the long-running SD70 family of American locomotives.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5d/UP_1996_%281290120334%29.jpg"},{"name":"EMD GP40-2","rarity":"rare","id":"emd-gp40-2","subtitle":"Diesel & Electric","details":"EMD's GP40-2 of 1972 was a 3,000 hp turbocharged road switcher, the refined successor to the GP40 and a fast-freight staple for decades of service.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/UP_1535_Leads_NB_Switcher_Iowa_Falls%2C_IA_6-28-18_%28cropped%29.jpg/1280px-UP_1535_Leads_NB_Switcher_Iowa_Falls%2C_IA_6-28-18_%28cropped%29.jpg"},{"name":"EMD F40PH","rarity":"rare","id":"emd-f40ph","subtitle":"Diesel & Electric","details":"EMD's F40PH of 1975 was a boxy passenger diesel derived from freight practice, serving as Amtrak's standard locomotive for two decades of operation.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/AMTK_315_Tun17_CZ_Nwcstle_Mar1995RP_-_Flickr_-_drewj1946.jpg/960px-AMTK_315_Tun17_CZ_Nwcstle_Mar1995RP_-_Flickr_-_drewj1946.jpg"},{"name":"EMD SW1500","rarity":"rare","id":"emd-sw1500","subtitle":"Diesel & Electric","details":"EMD's SW1500 of 1966 was a 1,500 hp end-cab switcher, built in large numbers for yard and industrial work across the United States and Canada.","image":"https://upload.wikimedia.org/wikipedia/commons/b/be/Metra4sw1500.jpg"},{"name":"GE U25B","rarity":"rare","id":"ge-u25b","subtitle":"Diesel & Electric","details":"GE's U25B of 1959 was the Universal Series road diesel, the U-boat design that established GE as a major American locomotive builder in its own right.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/New_Haven_2520_%28U25B%29_going_through_Danbury%2C_CT_on_Maybrook_freight_line%2C_July_28%2C_1968_%2822366087578%29.jpg/1280px-New_Haven_2520_%28U25B%29_going_through_Danbury%2C_CT_on_Maybrook_freight_line%2C_July_28%2C_1968_%2822366087578%29.jpg"},{"name":"British Rail Class 37","rarity":"rare","id":"br-class-37","subtitle":"Diesel & Electric","details":"The Class 37 of 1960 was an English Electric Type 3 diesel, its growling exhaust note making it an enduring emblem of British freight and passenger work.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/37019_Tinsley_1990.jpg/1280px-37019_Tinsley_1990.jpg"},{"name":"British Rail Class 66","rarity":"rare","id":"br-class-66","subtitle":"Diesel & Electric","details":"The Class 66 of 1998 was an American EMD design built for Britain, the JT42CWR locomotive that reshaped British heavy freight haulage for a generation.","image":"https://upload.wikimedia.org/wikipedia/commons/7/76/66534_on_container_train.jpg"},{"name":"DB Class 218","rarity":"rare","id":"db-class-218","subtitle":"Diesel & Electric","details":"The DB Class 218 of 1968 was a single-engine main-line diesel of the V160 family, built for express and regional work on non-electrified German routes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/218_813-4_K%C3%B6ln_Hbf%2C_2013.jpg/1280px-218_813-4_K%C3%B6ln_Hbf%2C_2013.jpg"},{"name":"SNCF CC 72000","rarity":"rare","id":"sncf-cc-72000","subtitle":"Diesel & Electric","details":"The SNCF CC 72000 of 1967 was a powerful six-axle Alsthom diesel, built to haul fast expresses at speed over France's non-electrified main lines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Longueau-ftdurail2013-cc_72084.JPG/1280px-Longueau-ftdurail2013-cc_72084.JPG"},{"name":"JNR Class DD51","rarity":"rare","id":"jnr-dd51","subtitle":"Diesel & Electric","details":"The JNR Class DD51 of 1962 was a centre-cab diesel-hydraulic with two engines, the standard main-line diesel for Japan's non-electrified trunk routes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/JNR_DD51_1027_20071003.jpg/1280px-JNR_DD51_1027_20071003.jpg"},{"name":"JNR Class EF66","rarity":"rare","id":"jnr-ef66","subtitle":"Diesel & Electric","details":"The JNR Class EF66 of 1968 was a high-power six-axle DC electric, built to haul fast freight expresses along the busy Tokaido corridor of Honshu.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/JNR_EF66-27_Nishi-Kokubunji_20220730.jpg/1280px-JNR_EF66-27_Nishi-Kokubunji_20220730.jpg"},{"name":"Siemens Charger SC-44","rarity":"rare","id":"siemens-charger-sc-44","subtitle":"Diesel & Electric","details":"The Siemens Charger SC-44 of 2015 was a Cummins-powered passenger diesel built for Amtrak state-corridor services in the Midwest, West and East.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Amtrak_locomotive_2102_%28cropped%29.jpg/1280px-Amtrak_locomotive_2102_%28cropped%29.jpg"},{"name":"EMD GP60","rarity":"rare","id":"emd-gp60","subtitle":"Diesel & Electric","details":"EMD's GP60 of 1985 was a four-axle freight diesel with microprocessor controls, built for fast intermodal service near the end of the long GP line.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/UP_1107.jpg/1280px-UP_1107.jpg"},{"name":"Soviet M62 (Taiga Drum)","rarity":"rare","id":"soviet-m62","subtitle":"Diesel & Electric","details":"The Soviet M62 of 1965 was a six-axle Kolomna diesel exported across Eastern Europe, nicknamed the Taiga Drum in East Germany for its deep exhaust beat.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/M62_diesel_locomotive_from_Luninets_depot.jpg/1280px-M62_diesel_locomotive_from_Luninets_depot.jpg"},{"name":"EMD GP9","rarity":"uncommon","id":"emd-gp9","subtitle":"Diesel & Electric","details":"EMD's GP9 of 1954 was the first-generation Geep, a 1,750 hp road switcher that dieselised branch lines and main lines alike across North America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Smoky_Hill_Railway_%26_Historical_Society_102_%28GP9%29_%28cropped%29.jpg/1280px-Smoky_Hill_Railway_%26_Historical_Society_102_%28GP9%29_%28cropped%29.jpg"},{"name":"EMD SD45","rarity":"uncommon","id":"emd-sd45","subtitle":"Diesel & Electric","details":"EMD's SD45 of 1965 used a 20-cylinder engine for 3,600 hp, its flared radiators marking it as the flagship of EMD's 40 Series freight era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/19990905_04_Wisconsin_Central_RR%2C_Oak_Park%2C_IL.jpg/1280px-19990905_04_Wisconsin_Central_RR%2C_Oak_Park%2C_IL.jpg"},{"name":"EMD GP30","rarity":"uncommon","id":"emd-gp30","subtitle":"Diesel & Electric","details":"EMD's GP30 of 1961 was a second-generation road switcher, easily recognised by the hump-backed cab roof and blistered styling of its carbody.","image":"https://upload.wikimedia.org/wikipedia/commons/8/88/ATSF_2705_CA_Cajon.jpg"},{"name":"EMD MP15DC","rarity":"uncommon","id":"emd-mp15dc","subtitle":"Diesel & Electric","details":"EMD's MP15DC of 1974 was a multipurpose end-cab switcher, built for yards, industrial plants and short-line railroads across North America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Loco_No._1363_in_Silvis.jpg/1280px-Loco_No._1363_in_Silvis.jpg"},{"name":"ALCO S-2 Switcher","rarity":"uncommon","id":"alco-s-2","subtitle":"Diesel & Electric","details":"ALCO's S-2 of 1940 was a turbocharged 1,000 hp end-cab switcher, a yard engine of the years when diesels were displacing steam in American yards.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Locomotive_1004_on_Port_Manatee_Railroad%2C_1971_%28cropped%29.jpg/1280px-Locomotive_1004_on_Port_Manatee_Railroad%2C_1971_%28cropped%29.jpg"},{"name":"Baldwin RF-16 Sharknose","rarity":"uncommon","id":"baldwin-rf-16-sharknose","subtitle":"Diesel & Electric","details":"Baldwin's RF-16 of 1950 was a cab freight diesel with Sharknose styling influenced by Raymond Loewy, its pointed profile a late Baldwin signature.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/New_York_Central_Baldwin_sharknose_locomotive.JPG"},{"name":"FM Train Master H-24-66","rarity":"uncommon","id":"fm-train-master","subtitle":"Diesel & Electric","details":"Fairbanks-Morse's Train Master of 1953 rated 2,400 hp from an opposed-piston engine, the most powerful single-engine diesel of its time.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/2_Southern_Pacific_Train_Masters_%2831191118836%29.jpg/1280px-2_Southern_Pacific_Train_Masters_%2831191118836%29.jpg"},{"name":"British Rail Class 20","rarity":"uncommon","id":"br-class-20","subtitle":"Diesel & Electric","details":"The Class 20 of 1957 was an English Electric Type 1 diesel nicknamed the Chopper, a single-cab design often worked in pairs on freight trains.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0f/20134_%26_20075_at_Ryecroft_Junction.jpg"},{"name":"British Rail Class 31","rarity":"uncommon","id":"br-class-31","subtitle":"Diesel & Electric","details":"The Class 31 of 1957 was a Brush Type 2 diesel with an A1A-A1A wheel arrangement, a long-lived type on secondary passenger and freight work in Britain.","image":"https://upload.wikimedia.org/wikipedia/commons/5/51/31249_%26_31314_at_Banbury.jpg"},{"name":"British Rail Class 40","rarity":"uncommon","id":"br-class-40","subtitle":"Diesel & Electric","details":"The Class 40 of 1958 was an English Electric Type 4 diesel, its whistling turbochargers marking the flagship of early British Rail diesel expresses.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/40104_-_Ayr_%2812074017243%29.jpg/1280px-40104_-_Ayr_%2812074017243%29.jpg"},{"name":"DB Class 110 (E10)","rarity":"uncommon","id":"db-class-110","subtitle":"Diesel & Electric","details":"The DB Class 110, built as the E10 from 1956, was a Bundesbahn standard electric, the box-cab express locomotive of West Germany's Einheitslok plan.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Locomotive_DB%2C_s%C3%A9rie_110_%28451-2%29.jpg"},{"name":"DB Class 140 (E40)","rarity":"uncommon","id":"db-class-140","subtitle":"Diesel & Electric","details":"The DB Class 140, built as the E40 from 1957, was the freight member of the Bundesbahn standard electric family and a decades-long heavy workhorse.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Db-140128-02.jpg"},{"name":"SNCF BB 67000","rarity":"uncommon","id":"sncf-bb-67000","subtitle":"Diesel & Electric","details":"The SNCF BB 67000 of 1963 headed a large four-axle main-line diesel family, built for mixed traffic on non-electrified lines across France.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Locomotive_BB_67000_in_Dieppe.jpg/1280px-Locomotive_BB_67000_in_Dieppe.jpg"},{"name":"JNR Class DE10","rarity":"uncommon","id":"jnr-de10","subtitle":"Diesel & Electric","details":"The JNR Class DE10 of 1966 was a five-axle diesel-hydraulic, the standard design for shunting, trip freight and branch-line work across Japan.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/DE10_1675.jpg/1280px-DE10_1675.jpg"},{"name":"JNR Class EF81","rarity":"uncommon","id":"jnr-ef81","subtitle":"Diesel & Electric","details":"The JNR Class EF81 of 1968 was a multi-voltage AC and DC electric, built for all-weather through work on coastal routes and long undersea tunnels.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/JRE-EF81-80.jpg/1280px-JRE-EF81-80.jpg"},{"name":"GE ES44AC Evolution Series","rarity":"uncommon","id":"ge-es44ac-evolution","subtitle":"Diesel & Electric","details":"GE's ES44AC of 2003 opened the Evolution Series, its GEVO engine powering the freight diesel family that succeeded the Dash 9 line in America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Burlington_Northern_and_Santa_Fe_Railway_-_6136_diesel_locomotive_%28ES44AC%29_%28Guernsey%2C_Wyoming%2C_USA%29_2_%2849603394797%29.jpg/1280px-Burlington_Northern_and_Santa_Fe_Railway_-_6136_diesel_locomotive_%28ES44AC%29_%28Guernsey%2C_Wyoming%2C_USA%29_2_%2849603394797%29.jpg"},{"name":"EMD SD60","rarity":"uncommon","id":"emd-sd60","subtitle":"Diesel & Electric","details":"EMD's SD60 of 1984 was a six-axle freight diesel that opened the microprocessor-controlled 60 Series, the generation after the Dash 2 line.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/The_last_oakway_SD60_%2845741008324%29.jpg/1280px-The_last_oakway_SD60_%2845741008324%29.jpg"},{"name":"GE AC4400CW","rarity":"uncommon","id":"ge-ac4400cw","subtitle":"Diesel & Electric","details":"GE's AC4400CW of 1993 was a 4,400 hp AC-traction freight diesel, the AC-drive counterpart to the Dash 9, built for heavy-haul coal and freight work.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Pair_of_CSX_AC4400CW_locomotives_at_Worcester%2C_MA.jpg/1280px-Pair_of_CSX_AC4400CW_locomotives_at_Worcester%2C_MA.jpg"},{"name":"MPI MP36PH-3S","rarity":"uncommon","id":"mpi-mp36ph","subtitle":"Diesel & Electric","details":"MotivePower's MP36PH-3S of 2002 was an F40-styled commuter diesel, built for regional and commuter railroads across the United States and Canada.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Trainroadrunner.jpg/1280px-Trainroadrunner.jpg"},{"name":"Bombardier ALP-46 Electric","rarity":"uncommon","id":"bombardier-alp-46","subtitle":"Diesel & Electric","details":"The ALP-46 of 2001 was a German-built electric for NJ Transit, hauling Northeast commuter expresses under wire into New York's Penn Station.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/NJ_Transit_4608_%2814117469959%29.jpg/1280px-NJ_Transit_4608_%2814117469959%29.jpg"},{"name":"British Rail Class 08 Shunter","rarity":"common","id":"br-class-08-shunter","subtitle":"Diesel & Electric","details":"The Class 08 of 1952 was British Rail's standard 0-6-0 diesel-electric yard shunter, with over 900 built for depots, stations and goods yards.","image":"https://upload.wikimedia.org/wikipedia/commons/a/aa/Class_08_08801_%28D3969%29_%286833336546%29.jpg"},{"name":"EMD SW7 Switcher","rarity":"common","id":"emd-sw7","subtitle":"Diesel & Electric","details":"EMD's SW7 of 1949 was a 1,200 hp end-cab switcher, a first-generation yard engine bought by freight railroads large and small across the United States.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Blue_Mountain_%26_Reading_1200_%28SW7%29_%2810570540684%29.jpg/1280px-Blue_Mountain_%26_Reading_1200_%28SW7%29_%2810570540684%29.jpg"},{"name":"GE 44-Tonner","rarity":"common","id":"ge-44-tonner","subtitle":"Diesel & Electric","details":"GE's 44-Tonner of 1940 was a small centre-cab industrial diesel, kept light enough for lightly built track, small plant railways and short lines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Central_of_Georgia_Railroad-_Savannah_Shops_and_Terminal_Facilities_%2808%29.jpg/1280px-Central_of_Georgia_Railroad-_Savannah_Shops_and_Terminal_Facilities_%2808%29.jpg"},{"name":"EMD GP15-1","rarity":"common","id":"emd-gp15-1","subtitle":"Diesel & Electric","details":"EMD's GP15-1 of 1976 was a light road switcher built with rebuilt components, aimed at yard and local freight work for cost-conscious railroads.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/USA-Vallejo-EMD_GP15-1_Locomotive.jpg/1280px-USA-Vallejo-EMD_GP15-1_Locomotive.jpg"},{"name":"EMD SD38-2","rarity":"common","id":"emd-sd38-2","subtitle":"Diesel & Electric","details":"EMD's SD38-2 of 1972 was a non-turbocharged six-axle diesel, a low-speed heavy switcher built for hump yards, steelworks and industrial service.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/LLPX_SD38-2_2808.jpg/1280px-LLPX_SD38-2_2808.jpg"},{"name":"EMD GP39-2","rarity":"common","id":"emd-gp39-2","subtitle":"Diesel & Electric","details":"EMD's GP39-2 of 1974 was a turbocharged mid-power road switcher, a 2,300 hp Geep built for local, transfer and branch-line freight service.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/BNSF_2866_EMD_GP39-2.jpg/1280px-BNSF_2866_EMD_GP39-2.jpg"},{"name":"British Rail Class 70 (PowerHaul)","rarity":"common","id":"br-class-70-diesel","subtitle":"Diesel & Electric","details":"The Class 70 of 2008 was a GE PowerHaul heavy freight diesel built in America for Freightliner, with a cab design unlike any earlier British type.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/British_Rail_Class_70_70020_of_freightliner_-_August_2017.jpg/1280px-British_Rail_Class_70_70020_of_freightliner_-_August_2017.jpg"},{"name":"DB Class 294 Shunter","rarity":"common","id":"db-class-294","subtitle":"Diesel & Electric","details":"The DB Class 294 grouped radio-controlled V90-family shunters rebuilt from the 1990s, the standard German engines for yards and trip-freight work.","image":"https://upload.wikimedia.org/wikipedia/commons/7/71/294-086_Dillenburg_23082002.jpg"},{"name":"DB Class 232 Ludmilla","rarity":"common","id":"db-class-232-ludmilla","subtitle":"Diesel & Electric","details":"Soviet-built six-axle diesel built in Luhansk in the 1970s; the heavy Lugansk family gained the Ludmilla nickname in reunified Germany.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/DB_232_614-8_%28Ludmilla%29_in_Piatra_Neamt.jpg/1280px-DB_232_614-8_%28Ludmilla%29_in_Piatra_Neamt.jpg"},{"name":"SNCF BB 60000","rarity":"common","id":"sncf-bb-60000","subtitle":"Diesel & Electric","details":"French four-axle diesel introduced in 2006; the Alstom and Vossloh Prima design handled shunting and trip-freight work for Fret SNCF.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/BB_60000_Eiffage_Rail%2C_chantier_Paris_Gare_de_l%27Est_%282%29.jpg/1280px-BB_60000_Eiffage_Rail%2C_chantier_Paris_Gare_de_l%27Est_%282%29.jpg"},{"name":"JR Freight Class DF200","rarity":"common","id":"jnr-df200","subtitle":"Diesel & Electric","details":"Japanese diesel-electric freight locomotive from 1992; the powerful Red Bear hauled heavy freight trains across the island of Hokkaido.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f0/JR_Freight_DF200-5_20100203.jpg"},{"name":"JNR Class DD16","rarity":"common","id":"jnr-dd16","subtitle":"Diesel & Electric","details":"Japanese light diesel-hydraulic locomotive from 1971; the small centre-cab design worked rural branch lines with light passenger trains.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/DD16_17_Otaru_Museum_20090830_%281%29.jpg/1280px-DD16_17_Otaru_Museum_20090830_%281%29.jpg"},{"name":"Indian WDM-3A","rarity":"common","id":"indian-wdm-3a","subtitle":"Diesel & Electric","details":"Indian broad-gauge ALCO diesel from a 1970s family; the versatile WDM workhorse dieselised main lines across the Indian Railways network.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/WDM_3A_locomotive_of_Indian_Railways.jpg/1280px-WDM_3A_locomotive_of_Indian_Railways.jpg"},{"name":"Indian WAP-7 Electric","rarity":"common","id":"indian-wap-7","subtitle":"Diesel & Electric","details":"Indian three-phase passenger electric locomotive from 1999; the high-power WAP design hauled Rajdhani and Shatabdi express services.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/SDAH_based_WAP-7_39207_pulling_13147_Sealdah%E2%80%93Bamanhat_Uttar_Banga_Express_04.jpg/1280px-SDAH_based_WAP-7_39207_pulling_13147_Sealdah%E2%80%93Bamanhat_Uttar_Banga_Express_04.jpg"},{"name":"South African Class 34","rarity":"common","id":"south-african-class-34","subtitle":"Diesel & Electric","details":"South African GE and EMD diesel family from 1971 onward; the versatile class became a standard main-line freight diesel for SAR services.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SAR%20Class%2034-000%2034-044.JPG?width=800"},{"name":"Australian NR Class","rarity":"common","id":"australian-nr-class","subtitle":"Diesel & Electric","details":"Australian GE Cv40-9i diesel locomotive from 1996; the NR Class standardised interstate freight haulage across the national network.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Pacific_National_freight_train_Virginia%2C_SA.jpg/1280px-Pacific_National_freight_train_Virginia%2C_SA.jpg"},{"name":"NSW 48 Class","rarity":"common","id":"nsw-48-class","subtitle":"Diesel & Electric","details":"Australian ALCO branch-line diesel from 1959; the small hood unit replaced steam power on country routes and light branch lines across New South Wales.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Goulburn_railway_station_2012-03-18_02.jpg/1280px-Goulburn_railway_station_2012-03-18_02.jpg"},{"name":"EMD NW2 Switcher","rarity":"common","id":"emd-nw2","subtitle":"Diesel & Electric","details":"American EMD end-cab switcher introduced in 1939; the compact cow-and-calf yard engine helped drive the early diesel transition in North America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Wichita_Falls_Railroad_Museum_October_2015_01_%28Missouri%E2%80%93Kansas%E2%80%93Texas_EMD_NW2_No._1029%29.jpg/1280px-Wichita_Falls_Railroad_Museum_October_2015_01_%28Missouri%E2%80%93Kansas%E2%80%93Texas_EMD_NW2_No._1029%29.jpg"},{"name":"ALCO HH600 Switcher","rarity":"common","id":"alco-hh600","subtitle":"Diesel & Electric","details":"American ALCO high-hood switcher introduced in 1931; a pioneer diesel design built for yard, transfer and industrial switching duties in the United States.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fe/New_Haven_Alco_HH600.jpg"},{"name":"GE B23-7","rarity":"common","id":"ge-b23-7","subtitle":"Diesel & Electric","details":"American GE four-axle road switcher from 1977; the 2,300-horsepower U-boat successor hauled freight for railroads across the country.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/BNSF_4258_GE_B23-7.JPG/1280px-BNSF_4258_GE_B23-7.JPG"},{"name":"GE P32AC-DM Dual-Mode","rarity":"common","id":"ge-p32ac-dm","subtitle":"Diesel & Electric","details":"American GE dual-mode passenger locomotive from 1995; the diesel and third-rail Genesis variant served New York services into Grand Central and Penn Station.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Metro-North_Heritage_P32AC-DM_203_1.jpg/1280px-Metro-North_Heritage_P32AC-DM_203_1.jpg"},{"name":"Siemens EuroSprinter ES64","rarity":"common","id":"siemens-eurosprinter-es64","subtitle":"Diesel & Electric","details":"German multi-system electric family from 1996; Taurus and EuroSprinter locomotives worked passenger and freight trains across Europe.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Wien_Meidling_Taurus_1116-168.jpg/1280px-Wien_Meidling_Taurus_1116-168.jpg"},{"name":"Bombardier TRAXX Electric","rarity":"common","id":"bombardier-traxx","subtitle":"Diesel & Electric","details":"European multi-system electric family launched in 1996; TRAXX locomotives hauled freight and passenger trains across national borders.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Bombardier_Electric_Traxx_29_locomotive_with_modal_shift_livery_in_Port_of_Antwerp.jpg"},{"name":"Vossloh G2000","rarity":"common","id":"vossloh-g2000","subtitle":"Diesel & Electric","details":"German diesel-hydraulic freight locomotive from 2000; the asymmetric-cab G2000 was leased to freight operators across much of continental Europe.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Vossloh_G2000-1BB.jpg/1280px-Vossloh_G2000-1BB.jpg"},{"name":"EMD GP7","rarity":"common","id":"emd-gp7","subtitle":"Diesel & Electric","details":"American EMD road switcher introduced in 1949; the original Geep launched the GP line, with an optional steam generator for passengers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/EMD_GP7_locomotives_.-_Railway_Museum_Toronto.jpg/1280px-EMD_GP7_locomotives_.-_Railway_Museum_Toronto.jpg"},{"name":"EMD GP18","rarity":"common","id":"emd-gp18","subtitle":"Diesel & Electric","details":"American EMD road switcher introduced in 1959; the late first-generation Geep bridged the GP9 era and the second-generation locomotive designs that followed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Missouri%20Pacific%201877%20%28GP18%29%20at%20Baytown%2C%20Texas%20in%20August%201980.png?width=800"},{"name":"SNCF BB 22200 Electric","rarity":"common","id":"sncf-bb-22200","subtitle":"Diesel & Electric","details":"French dual-voltage Nez Casse electric from 1976; the distinctive broken-nose family hauled passenger and freight trains across France.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/SNCF_BB_22200_-_22344_and_22349_at_Paris_Bercy.jpg/1280px-SNCF_BB_22200_-_22344_and_22349_at_Paris_Bercy.jpg"},{"name":"DB Class 101 Electric","rarity":"common","id":"db-class-101","subtitle":"Diesel & Electric","details":"German three-phase express electric from 1996; the Adtranz-built flagship hauled InterCity passenger trains on Deutsche Bahn routes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Peter_Stehlik_2010.06.13_058a.jpg/1280px-Peter_Stehlik_2010.06.13_058a.jpg"},{"name":"Series 0 Shinkansen","rarity":"chase","id":"series-0-shinkansen","subtitle":"High-Speed & Passenger","details":"The first Shinkansen type, entering service in 1964 for the Tokyo Olympics, with a distinctive rounded bullet nose and twin headlights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shinkansen%20type%200%20Hikari%2019890506b.jpg?width=800"},{"name":"Shinkansen E5 Series","rarity":"legendary","id":"shinkansen-e5-series","subtitle":"High-Speed & Passenger","details":"Tohoku Shinkansen flagship with a long duck-bill nose, designed for 320 km/h operation on high-speed services through northeast Japan to Shin-Aomori.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Series-E5-U2_Hayabusa-30.jpg/1280px-Series-E5-U2_Hayabusa-30.jpg"},{"name":"TGV Duplex","rarity":"legendary","id":"tgv-duplex","subtitle":"High-Speed & Passenger","details":"Double-deck French high-speed trainset that raised seating capacity on the busiest TGV routes without lengthening station platforms or adding extra paths.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Angoul%C3%AAme_16_TGV_Duplex_2013.jpg/1280px-Angoul%C3%AAme_16_TGV_Duplex_2013.jpg"},{"name":"ICE 3","rarity":"legendary","id":"ice-3","subtitle":"High-Speed & Passenger","details":"German high-speed family with distributed traction along the train, designed for 330 km/h operation and international ICE services across western Europe.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/ICE_3_K%C3%B6ln-M%C3%BClheim_2015-12-28.JPG/1280px-ICE_3_K%C3%B6ln-M%C3%BClheim_2015-12-28.JPG"},{"name":"Shanghai Maglev Transrapid","rarity":"legendary","id":"shanghai-maglev-transrapid","subtitle":"High-Speed & Passenger","details":"Magnetic-levitation line linking Shanghai with Pudong airport, famous for 431 km/h runs in commercial passenger service over its elevated guideway.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Shanghai_Maglev_2.jpg/1280px-Shanghai_Maglev_2.jpg"},{"name":"Acela Express","rarity":"legendary","id":"acela-express","subtitle":"High-Speed & Passenger","details":"Amtrak tilting trainset for the Northeast Corridor, introduced as the fastest passenger rail service in the United States on the Boston to Washington route.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Amtrak_Acela_Express_train_2275_approaching_Readville_station_March_2025_2.jpg/1280px-Amtrak_Acela_Express_train_2275_approaching_Readville_station_March_2025_2.jpg"},{"name":"Shinkansen N700S Series","rarity":"epic","id":"shinkansen-n700s-series","subtitle":"High-Speed & Passenger","details":"Tilting Shinkansen generation with active tilt and battery self-propulsion, built for fast and resilient operation on the Tokaido and Sanyo high-speed lines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Series-N700S-J2.jpg/1280px-Series-N700S-J2.jpg"},{"name":"CR400 Fuxing","rarity":"epic","id":"cr400-fuxing","subtitle":"High-Speed & Passenger","details":"Chinese standard high-speed trainset family designed for sustained 350 km/h operation on trunk routes across the national network.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/CR400AF_Fuxing_EMU.jpg/1280px-CR400AF_Fuxing_EMU.jpg"},{"name":"Frecciarossa 1000","rarity":"epic","id":"frecciarossa-1000","subtitle":"High-Speed & Passenger","details":"Italian flagship high-speed trainset certified for 360 km/h, styled and equipped for premium Frecciarossa services linking the major cities of Italy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/ETR_1000_leaving_Part-Dieu.jpg/1280px-ETR_1000_leaving_Part-Dieu.jpg"},{"name":"Eurostar e320","rarity":"epic","id":"eurostar-e320","subtitle":"High-Speed & Passenger","details":"Siemens Velaro trainsets built for Channel Tunnel services, linking London with Paris, Brussels and Amsterdam by high-speed rail under the Channel.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Velaro_e320_sur_LN3_par_Cramos.jpg/1280px-Velaro_e320_sur_LN3_par_Cramos.jpg"},{"name":"British Rail Class 390 Pendolino","rarity":"epic","id":"british-rail-class-390-pendolino","subtitle":"High-Speed & Passenger","details":"Tilting train built for Britain's West Coast Main Line, leaning into curves to cut journey times between London, the North West and Glasgow in Scotland.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Euston_station_MMB_61_390017.jpg/1280px-Euston_station_MMB_61_390017.jpg"},{"name":"Shinkansen E7 Series","rarity":"epic","id":"shinkansen-e7-series","subtitle":"High-Speed & Passenger","details":"Hokuriku Shinkansen trainset with a sky-and-river inspired livery and equipment for steep gradients and heavy snow on the route toward Nagano and Kanazawa.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Series-E7-F19.jpg/1280px-Series-E7-F19.jpg"},{"name":"TGV POS","rarity":"epic","id":"tgv-pos","subtitle":"High-Speed & Passenger","details":"French high-speed trainset formation that took part in the 574.8 km/h world rail speed record run achieved on the LGV Est line in April 2007.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/TGV_POS_%E2%80%94_gare_d%27Arras.jpg/1280px-TGV_POS_%E2%80%94_gare_d%27Arras.jpg"},{"name":"Talgo 350","rarity":"epic","id":"talgo-350","subtitle":"High-Speed & Passenger","details":"Spanish lightweight high-speed type with independently rotating wheels, used on AVE services and the Haramain line in Saudi Arabia.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/AVE_S-102_Renfe_Sevilla_Santa_Justa.JPG/1280px-AVE_S-102_Renfe_Sevilla_Santa_Justa.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"ICE 4","rarity":"rare","id":"ice-4","subtitle":"High-Speed & Passenger","details":"Modular German long-distance trainset family built to replace locomotive-hauled Intercity and EuroCity trains on national and cross-border routes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Buttenheim_DBAG_Class_412-20230407-RM-162955.jpg/1280px-Buttenheim_DBAG_Class_412-20230407-RM-162955.jpg"},{"name":"Shinkansen 500 Series","rarity":"rare","id":"shinkansen-500-series","subtitle":"High-Speed & Passenger","details":"Streamlined Shinkansen with a kingfisher-inspired nose, among the fastest series types in regular Japanese service during its front-line era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Shinkansen_500_series_W2_formation.jpg/1280px-Shinkansen_500_series_W2_formation.jpg"},{"name":"KTX-Sancheon","rarity":"rare","id":"ktx-sancheon","subtitle":"High-Speed & Passenger","details":"South Korean-built high-speed trainset that followed the imported KTX-I, serving Korea Train Express routes from Seoul to Busan and other major cities.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/KTX-Sancheon.jpg/1280px-KTX-Sancheon.jpg"},{"name":"Alfa Pendular","rarity":"rare","id":"alfa-pendular","subtitle":"High-Speed & Passenger","details":"Portuguese tilting train derived from the Pendolino family, linking Lisbon with Porto, Braga and the Algarve in fast intercity passenger services.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Alfa_Pendular_New_Livery.jpg/1280px-Alfa_Pendular_New_Livery.jpg"},{"name":"British Rail Class 800","rarity":"rare","id":"british-rail-class-800","subtitle":"High-Speed & Passenger","details":"Bi-mode Intercity Express Train built for Great Western and East Coast routes, running on electric or diesel power as each section of line required.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/GWR_Class_800_IETs_at_London_Paddington.jpg/1280px-GWR_Class_800_IETs_at_London_Paddington.jpg"},{"name":"SJ X 2000","rarity":"rare","id":"sj-x2000","subtitle":"High-Speed & Passenger","details":"Swedish tilting train that transformed Stockholm to Gothenburg journey times on curving conventional railway track, using active body tilt in service.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/X2000%2C_Malm%C3%B6_%28P1090553%29.jpg/1280px-X2000%2C_Malm%C3%B6_%28P1090553%29.jpg"},{"name":"AVE Class 103 Velaro E","rarity":"rare","id":"ave-class-103-velaro-e","subtitle":"High-Speed & Passenger","details":"Spanish Velaro variant built for Madrid to Barcelona high-speed services, designed for sustained operation at up to 350 km/h on the AVE network.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AVE%20Serie%20103%20Velaro%20%28Barcelona%20-%20Figueres%29%20-%20Llinars%20del%20Vall%C3%A8s%20%2811685467295%29.jpg?width=800"},{"name":"Shinkansen E2 Series","rarity":"rare","id":"shinkansen-e2-series","subtitle":"High-Speed & Passenger","details":"Workhorse Tohoku Shinkansen series that also formed the technical basis for exported Chinese CRH2 high-speed trainsets built for China Railways.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Series-E2-1000-J70.jpg/1280px-Series-E2-1000-J70.jpg"},{"name":"ETR 500","rarity":"rare","id":"etr-500","subtitle":"High-Speed & Passenger","details":"Italy's first generation of purpose-built high-speed trainsets, developed for the Direttissima corridors and fast services centred on Rome.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/ETR_500_Frecciarossa.jpg"},{"name":"British Rail Class 43 HST","rarity":"rare","id":"british-rail-class-43-hst","subtitle":"High-Speed & Passenger","details":"Power car of the InterCity 125, the diesel high-speed train that reshaped British intercity travel from the 1970s onward with 125 mph services.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/HST_InterCity_125_-_geograph.org.uk_-_7647719.jpg/1280px-HST_InterCity_125_-_geograph.org.uk_-_7647719.jpg"},{"name":"CRH380A Hexie","rarity":"rare","id":"crh380a-hexie","subtitle":"High-Speed & Passenger","details":"Chinese Harmony trainset generation developed for 380 km/h design speeds on new passenger-dedicated high-speed lines across the Chinese network.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/CRH380A-6020_20130414.jpg/1280px-CRH380A-6020_20130414.jpg"},{"name":"ICE 1","rarity":"uncommon","id":"ice-1","subtitle":"High-Speed & Passenger","details":"The original Intercity-Express trainset with two power cars, entering German high-speed passenger service in 1991 on routes from Hamburg and Munich.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/DB_ICE_1_M%C3%BCnchen_Hauptbahnhof_2015_01.jpg/1280px-DB_ICE_1_M%C3%BCnchen_Hauptbahnhof_2015_01.jpg"},{"name":"ICE T","rarity":"uncommon","id":"ice-t","subtitle":"High-Speed & Passenger","details":"Tilting ICE variant built for curving routes in southern and central Germany, where non-tilting ICE trains had to run at lower speeds in the curves.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/ICE_T_TZ_1163_-Osteebad_Binz-%2C_Frankfurt_%28LRM_20200520_124004-hdr%29.jpg/1280px-ICE_T_TZ_1163_-Osteebad_Binz-%2C_Frankfurt_%28LRM_20200520_124004-hdr%29.jpg"},{"name":"TGV Atlantique","rarity":"uncommon","id":"tgv-atlantique","subtitle":"High-Speed & Passenger","details":"Second-generation TGV trainset that set a world rail speed record of 515.3 km/h during a test run in May 1990 on the LGV Atlantique line.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/TGV_Atlantique_Rame_361_R01.jpg/1280px-TGV_Atlantique_Rame_361_R01.jpg"},{"name":"Shinkansen E4 Series Max","rarity":"uncommon","id":"shinkansen-e4-series-max","subtitle":"High-Speed & Passenger","details":"Double-deck all-seats Shinkansen built to move maximum passenger numbers on busy Tohoku corridor services, with two decks of seating throughout.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Shinkansen_%28bullet_train%29_%EF%BC%9A_The_Max-Yamabiko_super_express_%28Series_E4_train%29.JPG/1280px-Shinkansen_%28bullet_train%29_%EF%BC%9A_The_Max-Yamabiko_super_express_%28Series_E4_train%29.JPG"},{"name":"Shinkansen E6 Series Komachi","rarity":"uncommon","id":"shinkansen-e6-series-komachi","subtitle":"High-Speed & Passenger","details":"Mini-Shinkansen built for the Akita line, coupling with E5 sets for the Tokyo section and running on converted narrow-gauge railway track beyond Morioka.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Series-E6_Z14_Komachi.jpg/1280px-Series-E6_Z14_Komachi.jpg"},{"name":"Shinkansen 700 Series","rarity":"uncommon","id":"shinkansen-700-series","subtitle":"High-Speed & Passenger","details":"Duck-bill nosed Shinkansen generation that balanced high speed, quieter running and lower operating costs on Tokaido and Sanyo route services.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/JR_Central_Shinkansen_700.jpg/1280px-JR_Central_Shinkansen_700.jpg"},{"name":"Taiwan High Speed 700T","rarity":"uncommon","id":"taiwan-high-speed-700t","subtitle":"High-Speed & Passenger","details":"Taiwanese trainset derived from the Japanese 700 Series, linking Taipei with Kaohsiung in a journey of about ninety minutes at high speed.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/THSR_700T_TR17_20130907.jpg/1280px-THSR_700T_TR17_20130907.jpg"},{"name":"KTX-I","rarity":"uncommon","id":"ktx-i","subtitle":"High-Speed & Passenger","details":"The first Korea Train Express trainset, based on French TGV Reseau technology and built with Alstom and Rotem for services in South Korea.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/KTX-I_in_Busan_Station_%2815618537248%29.jpg/1280px-KTX-I_in_Busan_Station_%2815618537248%29.jpg"},{"name":"AGV 575 Italo","rarity":"uncommon","id":"agv-575-italo","subtitle":"High-Speed & Passenger","details":"Articulated AGV trainset operated by Italo in Italy, with traction motors distributed along the length of the train for high-speed services.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/AGV_.italo_Napoli_2.JPG/1280px-AGV_.italo_Napoli_2.JPG"},{"name":"British Rail Class 373 Eurostar","rarity":"uncommon","id":"british-rail-class-373-eurostar","subtitle":"High-Speed & Passenger","details":"The original Eurostar trainset built for Channel Tunnel services from London Waterloo and later St Pancras International to Paris and Brussels.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/British_Rail_Class_373.jpg/1280px-British_Rail_Class_373.jpg"},{"name":"APT Advanced Passenger Train","rarity":"uncommon","id":"apt-advanced-passenger-train","subtitle":"High-Speed & Passenger","details":"British experimental tilting train whose technology and research influenced Pendolino designs developed across Europe in later decades.","image":"https://upload.wikimedia.org/wikipedia/commons/9/91/APT_at_Crewe.jpg"},{"name":"Turbotrain RTG","rarity":"uncommon","id":"turbotrain-rtg","subtitle":"High-Speed & Passenger","details":"French gas-turbine trainset that brought fast intercity speeds to non-electrified routes during the 1970s, using aircraft-derived turbine power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Paris-Nord_turbotrain_1.jpg/1280px-Paris-Nord_turbotrain_1.jpg"},{"name":"CRH1 Hexie","rarity":"uncommon","id":"crh1-hexie","subtitle":"High-Speed & Passenger","details":"Early Chinese Harmony trainset based on Bombardier Regina technology, built for fast regional high-speed services in southern China.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/CRH1A_Hexie_EMU.jpg/1280px-CRH1A_Hexie_EMU.jpg"},{"name":"AVE Class 112","rarity":"uncommon","id":"ave-class-112","subtitle":"High-Speed & Passenger","details":"Spanish Talgo and Bombardier trainset built to expand AVE high-speed services beyond the first Madrid corridors to Valencia and other cities.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Tren_AVE%2C_en_la_estaci%C3%B3n_de_Valencia%2C_Espa%C3%B1a%2C_Serie_112_de_Renfe.JPG/1280px-Tren_AVE%2C_en_la_estaci%C3%B3n_de_Valencia%2C_Espa%C3%B1a%2C_Serie_112_de_Renfe.JPG"},{"name":"ETR 460 Pendolino","rarity":"uncommon","id":"etr-460-pendolino","subtitle":"High-Speed & Passenger","details":"Italian tilting train generation that spread Pendolino operation across Italy and into neighbouring European countries on intercity routes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Frecciabianca_ETR.460_at_Roma_Termini.jpg/1280px-Frecciabianca_ETR.460_at_Roma_Termini.jpg"},{"name":"British Rail Class 221 Super Voyager","rarity":"uncommon","id":"british-rail-class-221-super-voyager","subtitle":"High-Speed & Passenger","details":"Tilting diesel multiple unit built for Britain's CrossCountry routes, linking the South West with Scotland via Birmingham and the North of England.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Class_221_Super_Voyager_DMU.jpg/1280px-Class_221_Super_Voyager_DMU.jpg"},{"name":"Shinkansen 300 Series","rarity":"uncommon","id":"shinkansen-300-series","subtitle":"High-Speed & Passenger","details":"Lightweight aluminium Shinkansen that introduced faster Nozomi services on the Tokaido line in the early 1990s with a distinctive wedge nose.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Shinkansen_Series_300_%288062072906%29.jpg"},{"name":"Velaro RUS Sapsan","rarity":"uncommon","id":"velaro-rus-sapsan","subtitle":"High-Speed & Passenger","details":"Broad-gauge Velaro trainset built for Moscow to St Petersburg high-speed services in Russia under the Sapsan service name, meaning peregrine falcon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/%D0%AD%D0%92%D0%A12-02.JPG/1280px-%D0%AD%D0%92%D0%A12-02.JPG"},{"name":"Siemens Desiro","rarity":"common","id":"siemens-desiro","subtitle":"High-Speed & Passenger","details":"Modular diesel and electric multiple-unit family used for regional passenger services across Europe and beyond, in many lengths and layouts.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/460_009-4_%28Siemens_Desiro_Mainline%29_K%C3%B6ln_Hauptbahnhof_2015-11-01.JPG/1280px-460_009-4_%28Siemens_Desiro_Mainline%29_K%C3%B6ln_Hauptbahnhof_2015-11-01.JPG"},{"name":"Stadler FLIRT","rarity":"common","id":"stadler-flirt","subtitle":"High-Speed & Passenger","details":"Low-floor regional train family whose FLIRT name stands for Fast Light Intercity and Regional Train, with versions in service across many countries.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Endstation_Berne_-_NWB_RS4_der_RegioSBahn_Bremen-Niedersachsen_%28Stadler_Flirt_3%29.jpg/1280px-Endstation_Berne_-_NWB_RS4_der_RegioSBahn_Bremen-Niedersachsen_%28Stadler_Flirt_3%29.jpg"},{"name":"Alstom Coradia","rarity":"common","id":"alstom-coradia","subtitle":"High-Speed & Passenger","details":"Broad family of regional diesel and electric trains, with a name derived from the Greek word for through-running comfort and regional travel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alstom%20LHB%20Coradia%20LINT%20-%20Fulda%20Bahnhof%20-%202014.jpg?width=1024"},{"name":"Bombardier Talent","rarity":"common","id":"bombardier-talent","subtitle":"High-Speed & Passenger","details":"Lightweight articulated regional trainset design used widely for passenger services in Germany, Austria and Norway, with a low-floor layout.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/MRB_Bombardier_Talent_VT0012_01.jpg/1280px-MRB_Bombardier_Talent_VT0012_01.jpg"},{"name":"Siemens Charger","rarity":"common","id":"siemens-charger","subtitle":"High-Speed & Passenger","details":"American passenger diesel locomotive family built for Amtrak state corridor services and commuter rail operators across the United States.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Siemens_Charger_SC-44%2C_CDTX_2108_at_San_Jose_Diridon.jpg/1280px-Siemens_Charger_SC-44%2C_CDTX_2108_at_San_Jose_Diridon.jpg"},{"name":"GE Genesis P42","rarity":"common","id":"ge-genesis-p42","subtitle":"High-Speed & Passenger","details":"Monocoque passenger locomotive design that became Amtrak's long-distance diesel workhorse for a full generation of national network services.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/GE_Genesis_P42DC_at_Winona%2C_Minnesota%2C_July_2021.jpg/1280px-GE_Genesis_P42DC_at_Winona%2C_Minnesota%2C_July_2021.jpg"},{"name":"Amfleet I","rarity":"common","id":"amfleet-i","subtitle":"High-Speed & Passenger","details":"Budd-built stainless coach family from the 1970s that formed the core of many Northeast Corridor and eastern long-distance passenger trains.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Phase_VII_Amfleet_I_car_on_Amtrak_Vermonter_November_2025.jpg/1280px-Phase_VII_Amfleet_I_car_on_Amtrak_Vermonter_November_2025.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Superliner","rarity":"common","id":"superliner","subtitle":"High-Speed & Passenger","details":"Double-deck long-distance coaches built for Amtrak routes west of Chicago, with seating, sleeping and dining cars arranged over two levels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AMTK_322_with_the_San_Francisco_Zephyr_at_Cape_Horn%2C_CA_in_November_1980_-_2_Photos_%2830567817685%29.jpg?width=1024"},{"name":"Viewliner","rarity":"common","id":"viewliner","subtitle":"High-Speed & Passenger","details":"Single-level sleeping, dining and baggage cars built for Amtrak eastern long-distance trains, named for wide windows in their roomettes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Viewliner_61049_on_Amtrak_train_66_at_New_London_Union_Station%2C_September_2016.JPG?width=1024"},{"name":"British Rail Class 150 Sprinter","rarity":"common","id":"british-rail-class-150-sprinter","subtitle":"High-Speed & Passenger","details":"Second-generation Sprinter diesel units that replaced first-generation railcars on British branch and regional lines from the mid-1980s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LNWR_Class_150_at_Bedford.jpg?width=1024"},{"name":"British Rail Class 142 Pacer","rarity":"common","id":"british-rail-class-142-pacer","subtitle":"High-Speed & Passenger","details":"Lightweight Pacer railbuses built with bus components for lightly used British regional routes, known for a notably lively, bouncy ride.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/142080_at_Cardiff_Central_%2829805614596%29.jpg?width=1024"},{"name":"British Rail Class 170 Turbostar","rarity":"common","id":"british-rail-class-170-turbostar","subtitle":"High-Speed & Passenger","details":"Turbostar diesel units widely used on medium-distance regional routes across Britain, recognisable by their smooth, rounded cab fronts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/170461_at_Knaresborough_260623_%2853003817811%29.jpg?width=1024"},{"name":"British Rail Class 377 Electrostar","rarity":"common","id":"british-rail-class-377-electrostar","subtitle":"High-Speed & Passenger","details":"Electrostar electric units forming the backbone of Southern services south of London, working intensive commuter routes into the capital.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/377163_at_Hastings.jpg?width=1024"},{"name":"British Rail Class 700","rarity":"common","id":"british-rail-class-700","subtitle":"High-Speed & Passenger","details":"Desiro City electric units built for Thameslink services through central London, designed for metro-style capacity on cross-city routes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20220519_Thameslink_700032.jpg?width=1024"},{"name":"JR E231 Series","rarity":"common","id":"jr-e231-series","subtitle":"High-Speed & Passenger","details":"Japanese commuter train family built in large numbers for Tokyo-area services, including the famous Yamanote loop line around the city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JRE_Series-E231_B11.jpg?width=1024"},{"name":"JR E233 Series","rarity":"common","id":"jr-e233-series","subtitle":"High-Speed & Passenger","details":"Successor commuter family to the E231, standardised across many Tokyo-area JR East routes with wider bodies and duplicated key systems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JRE_E233Series.jpg?width=1024"},{"name":"ICE 2","rarity":"common","id":"ice-2","subtitle":"High-Speed & Passenger","details":"Half-length ICE formation with a single power car and a driving trailer, built to run in pairs and split apart for separate destinations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Angermund_ICE2_duo_402_031-030_als_ICE_942_Berlin_Hbf-K%C3%B6ln_Hbf_%2833754015610%29.jpg?width=1024"},{"name":"TGV Reseau","rarity":"common","id":"tgv-reseau","subtitle":"High-Speed & Passenger","details":"Network generation of TGV built to run across all French high-speed lines and into neighbouring countries on international services.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TGV_R%C3%A9seau_550%2C_Cesson-S%C3%A9vign%C3%A9.jpg?width=1024"},{"name":"EMD F59PHI","rarity":"common","id":"emd-f59phi","subtitle":"High-Speed & Passenger","details":"Streamlined North American passenger locomotive built in the 1990s for Amtrak and commuter agencies, with a distinctive rounded cab design.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/City_of_High_Point_with_the_Piedmont_at_Salisbury%2C_August_2016_%28cropped%29.jpg?width=1024"},{"name":"Budd Metroliner","rarity":"common","id":"budd-metroliner","subtitle":"High-Speed & Passenger","details":"American electric multiple units that brought high-speed ambitions to the Northeast Corridor in the late 1960s between New York and Washington.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southbound_Amtrak_Metroliner_with_cab_car_880_at_Bowie%2C_December_1980.jpg?width=1024"},{"name":"Shinkansen E3 Series Tsubasa","rarity":"common","id":"shinkansen-e3-series-tsubasa","subtitle":"High-Speed & Passenger","details":"Mini-Shinkansen built for the Yamagata Tsubasa service, running to Tokyo coupled with larger Tohoku sets before branching onto narrower lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Series-E3-1000_L53_Tsubasa.jpg?width=1024"},{"name":"KTX-Eum","rarity":"common","id":"korail-ktx-eum","subtitle":"High-Speed & Passenger","details":"Korean distributed-traction trainset built for semi-high-speed services at up to 260 km/h, with power spread through the train for strong acceleration.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20220911_Cheongnyangni_Station_KTX-Eum_504.jpg?width=1024"}]});
